def _apply_cached_indexes(self, cached_indexes, persist=False):
        """Reassign various resampler index attributes."""
        if cached_indexes is not None:
            # reassign the index
            self.index = cached_indexes['index']
            if self.index.name is None:
                self.index.name = 'time'

            # reassign the groupby_index
            self.groupby_index = cached_indexes['groupby_index']

            # reassign the columns
            self.columns = cached_indexes['columns']

            if persist:
                self._save_cached_indexes()
